const slides = context.presentation.slides;
slides.load("items");
await context.sync();

const out = [];
const start = 0, end = 40; // slides 1-40
for (let i = start; i < end && i < slides.items.length; i++) {
  const slide = slides.items[i];
  const layout = slide.layout;
  layout.load("name");
  const shapes = slide.shapes;
  shapes.load("items/id,items/name,items/type,items/left,items/top,items/width,items/height");
  await context.sync();
  const shapeEntries = shapes.items.map(sh => {
    const tf = sh.getTextFrameOrNullObject();
    tf.load("hasText");
    return { sh, tf };
  });
  await context.sync();
  // load text ranges
  const withText = [];
  for (const e of shapeEntries) {
    if (!e.tf.isNullObject && e.tf.hasText) {
      e.tf.textRange.load("text");
      withText.push(e);
    }
  }
  await context.sync();
  const shapeData = shapeEntries.map(e => ({
    id: e.sh.id,
    name: e.sh.name,
    type: e.sh.type,
    x: Math.round(e.sh.left), y: Math.round(e.sh.top),
    w: Math.round(e.sh.width), h: Math.round(e.sh.height),
    text: (!e.tf.isNullObject && e.tf.hasText) ? e.tf.textRange.text : ""
  }));
  out.push({ pos: i+1, slideId: slide.id, layout: layout.name, shapes: shapeData });
}

const existing = blobs.getJSON("deckdump") || [];
const merged = existing.concat(out);
blobs.setJSON("deckdump", merged);

// compact summary
const summary = out.map(s => ({
  pos: s.pos, layout: s.layout, nShapes: s.shapes.length,
  textChars: s.shapes.reduce((a,b)=>a+b.text.length,0),
  imgs: s.shapes.filter(x=>x.type==="Image"||x.type==="Picture").length
}));
return { extracted: out.length, totalStashed: merged.length, summary };
